package rars.dataflowanalysis;

import rars.ProgramStatement;
import rars.riscv.Instruction;

import java.util.*;

/**
 * Takes care of building the Data Dependancy Graph from the instructions
 * generated by the RARS assembly.
 */
public class DDGBuilder {

    private final SignAnalysis analysis;

    public DDGBuilder(SignAnalysis analysis) {
        this.analysis = analysis;
    }

    public List<DDGNode> build() {
        int n = analysis.size();
        if (n == 0) return Collections.emptyList();

        List<DDGNode> nodes = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            ProgramStatement stmt = analysis.instruction(i);
            SignState after = analysis.stateAfter(i);
            int dst = destRegister(stmt);
            Sign outSign = (dst >= 0) ? after.get(dst) : Sign.BOTTOM;
            boolean isExt = isExternalCall(stmt);
            String callLbl = isExt ? extractCallLabel(stmt) : null;
            nodes.add(new DDGNode(i, stmt, outSign, isExt, callLbl));
        }

        @SuppressWarnings("unchecked")
        Set<Integer>[] succs = new Set[n];
        for (int i = 0; i < n; i++) succs[i] = new LinkedHashSet<>();

        for (int i = 0; i < n; i++) {
            ProgramStatement stmt = analysis.instruction(i);
            Instruction instr = stmt.getInstruction();
            if (instr == null) {
                if (i + 1 < n) succs[i].add(i + 1);
                continue;
            }
            String m = instr.getName().toLowerCase();
            int[] ops = stmt.getOperands();
            int pc = stmt.getAddress();

            if (m.equals("jal") && ops != null && ops.length >= 2 && ops[0] == 0) {
                int targetAbs = pc + ops[ops.length - 1];
                int tIdx = addrToIndex(targetAbs);
                if (tIdx >= 0) succs[i].add(tIdx);
                // no fall-through
                continue;
            }

            if (m.equals("jal") && ops != null && ops.length >= 2) {
                if (i + 1 < n) succs[i].add(i + 1);
                continue;
            }

            if (isBranchMnemonic(m) && ops != null) {
                if (i + 1 < n) succs[i].add(i + 1);
                int offsetIdx = (m.equals("beq") || m.equals("bne") || m.equals("blt")
                        || m.equals("bltu") || m.equals("bge") || m.equals("bgeu"))
                        ? 2 : 1; 
                if (ops.length > offsetIdx) {
                    int targetAbs = pc + ops[offsetIdx];
                    int tIdx = addrToIndex(targetAbs);
                    if (tIdx >= 0) succs[i].add(tIdx);
                }
                continue;
            }
            if (i + 1 < n) succs[i].add(i + 1);
        }

        int[][] reachIn  = new int[n][SignState.NUM_REGS];
        int[][] reachOut = new int[n][SignState.NUM_REGS];
        for (int[] row : reachIn)  Arrays.fill(row, -1);
        for (int[] row : reachOut) Arrays.fill(row, -1);

        Queue<Integer> worklist = new ArrayDeque<>();
        for (int i = 0; i < n; i++) worklist.add(i);

        while (!worklist.isEmpty()) {
            int i = worklist.poll();

            int[] out = Arrays.copyOf(reachIn[i], SignState.NUM_REGS);
            int dst = destRegister(analysis.instruction(i));
            if (dst > 0) out[dst] = i;
            if (nodes.get(i).isExternalCall) {
                int[] cs = {1, 5, 6, 7, 10, 11, 12, 13, 14, 15, 16, 17, 28, 29, 30, 31};
                for (int r : cs) out[r] = i;
            }

            if (!Arrays.equals(reachOut[i], out)) {
                reachOut[i] = out;
                for (int succ : succs[i]) {
                    boolean changed = false;
                    for (int r = 0; r < SignState.NUM_REGS; r++) {
                        int existing = reachIn[succ][r];
                        int incoming = out[r];
                        if (incoming == -1) continue;
                        if (existing == -1) {
                            reachIn[succ][r] = incoming;
                            changed = true;
                        } else if (existing != incoming) {
                            if (reachIn[succ][r] != -2) {
                                reachIn[succ][r] = -2;
                                changed = true;
                            }
                        }
                    }
                    if (changed) worklist.add(succ);
                }
            }
        }

        Set<String> edgeSet = new LinkedHashSet<>();

        for (int i = 0; i < n; i++) {
            ProgramStatement stmt = analysis.instruction(i);
            DDGNode useNode = nodes.get(i);
            SignState before = (i == 0) ? new SignState() : analysis.stateAfter(i - 1);

            int[] srcs = sourceRegisters(stmt);
            for (int src : srcs) {
                if (src <= 0 || src >= SignState.NUM_REGS) continue;
                if (src == 17) continue; // I decided to skip over a7 because it is a SYSCALL register
                int defIdx = reachIn[i][src];
                if (defIdx == -1) continue; 
                if (defIdx == -2) {
                    continue;
                }
                String key = defIdx + "->" + i + ":" + src;
                if (edgeSet.add(key)) {
                    DDGNode defNode = nodes.get(defIdx);
                    Sign edgeSign = before.get(src);
                    defNode.outEdges.add(new DDGEdge(defNode, useNode, src, edgeSign));
                }
            }
        }

        return nodes;
    }

    private int addrToIndex(int targetAbs) {
        int n = analysis.size();
        for (int i = 0; i < n; i++) {
            if (analysis.instruction(i).getAddress() == targetAbs) return i;
        }
        return -1;
    }

    private boolean isBranchMnemonic(String m) {
        switch (m) {
            case "beq": case "bne": case "blt": case "bltu":
            case "bge": case "bgeu": case "beqz": case "bnez":
            case "bltz": case "bgez": case "bgtz": case "blez":
                return true;
            default: return false;
        }
    }

    private int destRegister(ProgramStatement stmt) {
        Instruction instr = stmt.getInstruction();
        if (instr == null) return -1;
        String m = instr.getName().toLowerCase();
        int[] ops = stmt.getOperands();
        if (ops == null || ops.length == 0) return -1;
        switch (m) {
            case "sb": case "sh": case "sw": case "sd":
            case "beq": case "bne": case "blt": case "bltu":
            case "bge": case "bgeu": case "beqz": case "bnez":
            case "bltz": case "bgez": case "bgtz": case "blez":
            case "ecall": case "ebreak":
                return -1;
            default:
                return (ops.length >= 1) ? ops[0] : -1;
        }
    }

    private int[] sourceRegisters(ProgramStatement stmt) {
        Instruction instr = stmt.getInstruction();
        if (instr == null) return new int[0];
        String m = instr.getName().toLowerCase();
        int[] ops = stmt.getOperands();
        if (ops == null || ops.length == 0) return new int[0];
        switch (m) {
            case "add": case "addw": case "sub": case "subw":
            case "mul": case "mulw": case "div": case "divu":
            case "divw": case "divuw": case "rem": case "remu":
            case "remw": case "remuw":
            case "and": case "or": case "xor":
            case "sll": case "srl": case "sra":
            case "sllw": case "srlw": case "sraw":
            case "slt": case "sltu":
                return ops.length >= 3 ? new int[]{ops[1], ops[2]} : new int[0];
            case "addi": case "addiw":
            case "andi": case "ori": case "xori":
            case "slli": case "srli": case "srai":
            case "slliw": case "srliw": case "sraiw":
            case "slti": case "sltiu":
                return ops.length >= 2 ? new int[]{ops[1]} : new int[0];
            case "lb": case "lbu": case "lh": case "lhu":
            case "lw": case "lwu": case "ld":
                return ops.length >= 2 ? new int[]{ops[1]} : new int[0];
            case "sb": case "sh": case "sw": case "sd":
                return ops.length >= 2 ? new int[]{ops[0], ops[1]} : new int[0];
            case "beq": case "bne": case "blt": case "bltu":
            case "bge": case "bgeu":
                return ops.length >= 2 ? new int[]{ops[0], ops[1]} : new int[0];
            case "beqz": case "bnez": case "bltz": case "bgez":
            case "bgtz": case "blez":
                return ops.length >= 1 ? new int[]{ops[0]} : new int[0];
            case "mv":
                return ops.length >= 2 ? new int[]{ops[1]} : new int[0];
            case "neg": case "negw": case "not":
                return ops.length >= 2 ? new int[]{ops[1]} : new int[0];
            case "jalr":
                return ops.length >= 2 ? new int[]{ops[1]} : new int[0];
            case "jal": case "lui": case "auipc": case "li":
                return new int[0];
            default:
                return new int[0];
        }
    }

    private boolean isExternalCall(ProgramStatement stmt) {
        Instruction instr = stmt.getInstruction();
        if (instr == null) return false;
        String m = instr.getName().toLowerCase();
        int[] ops = stmt.getOperands();
        if (ops == null) return false;
        if (m.equals("jalr")) return true;
        if (m.equals("jal") && ops.length >= 2) {
            int n = analysis.size();
            int targetAbs = stmt.getAddress() + ops[ops.length - 1];
            int minAddr = analysis.instruction(0).getAddress();
            int maxAddr = analysis.instruction(n - 1).getAddress();
            return targetAbs < minAddr || targetAbs > maxAddr;
        }
        return false;
    }

    private String extractCallLabel(ProgramStatement stmt) {
        String src = stmt.getSource();
        if (src == null) return null;
        src = src.trim();
        int hash = src.indexOf('#');
        if (hash >= 0) src = src.substring(0, hash).trim();
        String[] parts = src.split("[\\s,]+");
        return parts.length > 0 ? parts[parts.length - 1] : null;
    }
}